window.HOEREN_TESTS[75] = {"id":"in-der-buchhandlung","name":"In der Buchhandlung","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Willkommen in unserer Buchhandlung. Heute Abend um 19 Uhr liest eine bekannte Autorin aus ihrem neuen Roman, kein Konzert und kein Flohmarkt. Der Eintritt ist frei, aber die Plätze sind begrenzt. Wer ein Buch kauft, bekommt es signiert. Bitte kommen Sie früh. Wir freuen uns auf einen schönen Abend!","gender":"f","q":"Was passiert heute Abend?","opts":["Ein Flohmarkt.","Ein Konzert.","Eine Lesung mit einer Autorin."],"correct":2},{"transcript":"Hallo Tom, hier ist Markus. Du, ich suche ein Geschenk für meine Nichte zum zehnten Geburtstag, nicht für meinen Sohn und nicht für meine Frau. Sie liest sehr gern, aber ich kenne keine Kinderbücher. Du hast doch Kinder. Kannst du mir etwas empfehlen? Vielleicht ein Abenteuerbuch? Ruf zurück, ich gehe morgen in die Buchhandlung. Danke!","gender":"m","q":"Für wen sucht Markus ein Geschenk?","opts":["Für seinen Sohn.","Für seine Nichte.","Für seine Frau."],"correct":1},{"transcript":"Achtung Kunden: Das Buch, das Sie bestellt haben, ist da — aber nicht das gebundene Buch und kein E-Book, sondern leider nur das Taschenbuch. Der Verlag hat das teure nicht geschickt. Wenn Sie trotzdem das Taschenbuch möchten, ist es günstiger. Sonst bestellen wir neu. Bitte sagen Sie an der Kasse Bescheid. Danke!","gender":"m","q":"Welches Buch ist gekommen?","opts":["Das Taschenbuch.","Das gebundene Buch.","Ein E-Book."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Ich habe in der Buchhandlung einen Lesekreis entdeckt, keinen Sprachkurs und kein Café. Einmal im Monat trifft man sich und spricht über ein Buch. Klingt das nicht toll? Wir können zusammen hingehen, das nächste Buch ist ein Krimi. Du liest doch gern Krimis. Sag Bescheid, bis bald!","gender":"f","q":"Was hat Anna entdeckt?","opts":["Einen Lesekreis.","Einen Sprachkurs.","Ein Café."],"correct":0},{"transcript":"Liebe Kunden: Mit unserer Kundenkarte sammeln Sie bei jedem Einkauf Punkte. Ab hundert Punkten bekommen Sie einen Gutschein über zehn Euro, kein kostenloses Buch und keine kostenlose Karte. Die Karte ist kostenlos. Außerdem informieren wir Sie über neue Bücher und Lesungen. Fragen Sie einfach an der Kasse. Es lohnt sich!","gender":"f","q":"Was bekommt man ab hundert Punkten?","opts":["Ein kostenloses Buch.","Einen Gutschein über zehn Euro.","Eine kostenlose Karte."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer liest was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Wir stehen schon lange im Laden. Hast du unseren Zettel dabei?"},{"speaker":"Lisa","gender":"f","text":"Er liegt in meiner Tasche. Fünf Freunde wollen heute lesen und jeder sucht etwas anderes."},{"speaker":"Lukas","gender":"m","text":"Dann fange ich an. Ich nehme Krimis mit, weil ich abends im Bett gern lese."},{"speaker":"Lisa","gender":"f","text":"Die stehen links unten. Liest jemand bei euch Gedichte?"},{"speaker":"Lukas","gender":"m","text":"Gedichte will bei uns keiner. Die bleiben einfach im Laden."},{"speaker":"Lisa","gender":"f","text":"Ich selbst lese am Wochenende Liebesromane auf dem Sofa."},{"speaker":"Lukas","gender":"m","text":"Die lege ich dir dazu. Was braucht Tom für die Schule?"},{"speaker":"Lisa","gender":"f","text":"Tom sucht Sachbücher über die Welt. Er schreibt morgen eine Arbeit."},{"speaker":"Lukas","gender":"m","text":"Die dicken stehen hinten. Liegen dort auch Biografien?"},{"speaker":"Lisa","gender":"f","text":"Biografien nimmt heute auch keiner mit. Die sind lang und schwer."},{"speaker":"Lukas","gender":"m","text":"Ich hole zwei Sachbücher für ihn. Steht bei Sara auch etwas?"},{"speaker":"Lisa","gender":"f","text":"Sara möchte Kochbücher mit großen Bildern. Am Sonntag kocht sie für ihre Mutter."},{"speaker":"Lukas","gender":"m","text":"Dann nehmen wir das Buch über Suppe."},{"speaker":"Lisa","gender":"f","text":"Tim liest in der Bahn gern Comics. Er will sie bunt für den kurzen Weg."},{"speaker":"Lukas","gender":"m","text":"Die liegen neben der Kasse."},{"speaker":"Lisa","gender":"f","text":"Ich zahle und dann fahren wir nach Hause."}],"options":[{"letter":"a","text":"Liebesromane"},{"letter":"b","text":"Biografien"},{"letter":"c","text":"Krimis"},{"letter":"d","text":"Gedichte"},{"letter":"e","text":"Comics"},{"letter":"f","text":"Reiseführer"},{"letter":"g","text":"Kochbücher"},{"letter":"h","text":"Kinderbücher"},{"letter":"i","text":"Sachbücher"}],"items":[{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"a"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"g"},{"person":"Tim","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, haben Sie dieses Buch da, sofort? Oder erst nächste Woche?"},{"speaker":"Verkäufer","gender":"m","text":"Im Moment nicht, also nicht sofort. Aber ich bestelle es."},{"speaker":"Kundin","gender":"f","text":"Wie lange dauert das, nächste Woche?"},{"speaker":"Verkäufer","gender":"m","text":"Bis morgen Nachmittag ist es da, nicht nächste Woche und nicht sofort."},{"speaker":"Kundin","gender":"f","text":"Super, morgen Nachmittag. Dann komme ich morgen wieder. Danke."}],"q":"Wann ist das Buch da?","opts":["Sofort.","Nächste Woche.","Morgen Nachmittag."],"correct":2},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, was kostet dieses Buch? 25 Euro oder 15 Euro?"},{"speaker":"Verkäuferin","gender":"f","text":"Gebunden 25 Euro, als Taschenbuch 12 Euro, nicht 15 Euro."},{"speaker":"Mann","gender":"m","text":"Dann nehme ich das Taschenbuch für 12 Euro, nicht das gebundene."},{"speaker":"Verkäuferin","gender":"f","text":"Gute Wahl, 12 Euro bitte. Das Taschenbuch ist 12, nicht 15."},{"speaker":"Mann","gender":"m","text":"Hier sind 12 Euro bitte. Danke, das Taschenbuch reicht mir völlig aus."}],"q":"Was kostet das Taschenbuch?","opts":["25 Euro.","15 Euro.","12 Euro."],"correct":2},{"lines":[{"speaker":"Vater","gender":"m","text":"Guten Tag, ich suche ein Buch für einen Sechsjährigen. Ein dickes Romanbuch oder ein Sachbuch?"},{"speaker":"Verkäuferin","gender":"f","text":"Liest er schon selbst? Ein dicker Roman ist oft zu schwer."},{"speaker":"Vater","gender":"m","text":"Noch nicht, ich lese vor. Ein Sachbuch will er nicht."},{"speaker":"Verkäuferin","gender":"f","text":"Dann ein Bilderbuch mit kurzen Texten, kein dicker Roman und kein Sachbuch."},{"speaker":"Vater","gender":"m","text":"Perfekt, ein Bilderbuch mit kurzen Texten. Danke für den Tipp."}],"q":"Was empfiehlt die Verkäuferin?","opts":["Ein dickes Romanbuch.","Ein Bilderbuch mit kurzen Texten.","Ein Sachbuch."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, kann ich das Buch umtauschen? Es ist nicht kaputt und nicht zu teuer."},{"speaker":"Verkäufer","gender":"m","text":"Warum, gefällt es nicht? Ist es kaputt?"},{"speaker":"Frau","gender":"f","text":"Nein, ich habe das Buch schon, ein Geschenk doppelt. Zu teuer ist es nicht."},{"speaker":"Verkäufer","gender":"m","text":"Kein Problem, mit Bon geht der Umtausch. Sie haben es schon, deshalb tauschen wir."},{"speaker":"Frau","gender":"f","text":"Danke, hier ist der Bon. Ich habe das Buch wirklich schon."}],"q":"Warum möchte die Frau umtauschen?","opts":["Es ist kaputt.","Sie hat das Buch schon.","Es ist zu teuer."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, wann ist die Lesung heute? Im Erdgeschoss oder im Keller?"},{"speaker":"Verkäuferin","gender":"f","text":"Um 19 Uhr, oben im ersten Stock, nicht im Erdgeschoss und nicht im Keller."},{"speaker":"Kunde","gender":"m","text":"Muss ich mich anmelden?"},{"speaker":"Verkäuferin","gender":"f","text":"Nein, einfach vorbeikommen, erster Stock um 19 Uhr."},{"speaker":"Kunde","gender":"m","text":"Gut, dann komme ich um 19 Uhr in den ersten Stock. Danke."}],"q":"Wo findet die Lesung statt?","opts":["Im ersten Stock.","Im Erdgeschoss.","Im Keller."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Lehmann, einer Buchhändlerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Lehmann, viele kaufen Bücher heute im Internet. Wie überlebt eine kleine Buchhandlung?"},{"speaker":"Lehmann","gender":"f","text":"Durch Beratung und Persönlichkeit. Im Internet bekommen Sie tausend Treffer, aber keinen Rat. Bei mir können Sie fragen: Ich habe dieses Buch geliebt, was passt noch zu mir? Diese persönliche Empfehlung ist unser großer Vorteil. Den kann kein Computer ersetzen."},{"speaker":"Reporter","gender":"m","text":"Lesen die Menschen heute weniger?"},{"speaker":"Lehmann","gender":"f","text":"Das höre ich oft, aber ich finde es nicht. Viele lesen sogar mehr, nur anders — auch auf dem E-Reader. Aber gerade junge Leute kommen wieder zum gedruckten Buch zurück. Sie wollen etwas in der Hand halten. Das gedruckte Buch ist nicht tot, im Gegenteil."},{"speaker":"Reporter","gender":"m","text":"Was empfehlen Sie am liebsten?"},{"speaker":"Lehmann","gender":"f","text":"Bücher von kleinen, unbekannten Autoren. Die großen Bestseller verkaufen sich von selbst. Aber die wahren Schätze sind oft die leisen Bücher, die niemand kennt. Wenn ich so ein Buch jemandem in die Hand drücke und es ihm gefällt, ist das mein schönster Moment."},{"speaker":"Reporter","gender":"m","text":"Veranstalten Sie auch Lesungen?"},{"speaker":"Lehmann","gender":"f","text":"Ja, regelmäßig, und sie sind immer voll. Die Leute wollen die Autoren erleben, Fragen stellen, ein signiertes Buch mitnehmen. Solche Abende verbinden die Menschen. Eine Buchhandlung ist heute mehr als ein Laden — sie ist ein Treffpunkt für die Nachbarschaft."},{"speaker":"Reporter","gender":"m","text":"Was wünschen Sie sich für die Zukunft?"},{"speaker":"Lehmann","gender":"f","text":"Dass die Menschen den Wert kleiner Läden erkennen. Wer bei uns kauft, hält das Viertel lebendig. Ein bisschen teurer als im Internet, ja, aber dafür bekommt man echte Beratung und ein Lächeln. Lesen Sie, und kaufen Sie Ihre Bücher bei einem Menschen, nicht bei einer Maschine."}],"items":[{"q":"Frau Lehmann sieht die persönliche Beratung als großen Vorteil.","correct":"ja"},{"q":"Sie findet, dass junge Leute nur noch E-Reader benutzen.","correct":"nein"},{"q":"Sie empfiehlt am liebsten unbekannte Autoren.","correct":"ja"},{"q":"Ihre Lesungen sind oft schlecht besucht.","correct":"nein"},{"q":"Sie wünscht sich, dass die Menschen kleine Läden schätzen.","correct":"ja"}]}]};
